import axios from 'axios';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { API_URLS } from '~/shared/api/api-urls';
import { TokenItemType } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import { resultify } from '~/shared/lib/utils/resultify';
import { AccountValidRequestDTO, AccountValidResponseDTO } from './dtos/account-valid';
import { CreateWalletRequestDTO, CreateWalletResponseDTO } from './dtos/create-wallet';
import { DeleteWalletRequestDTO, DeleteWalletResponseDTO } from './dtos/delete-wallet';
import { WalletHistoryDetailRequestDTO, WalletHistoryDetailResponseDTO } from './dtos/wallet-history-detail';
import { WalletHistoryListRequestDTO, WalletHistoryListResponseDTO } from './dtos/wallet-history-list';

export const walletApi = {
  // 계좌 유효성 검사
  accountValid: ({ tbAcnutMastr }: AccountValidRequestDTO) =>
    resultify(
      axios.post<AccountValidResponseDTO>(`${API_URLS.accountValid}`, {
        tbAcnutMastr,
      }),
    ),
  // 지갑 생성
  createWallet: ({ tbCstmrMastr }: CreateWalletRequestDTO) =>
    resultify(
      axios.post<CreateWalletResponseDTO>(`${API_URLS.createWallet}`, {
        tbCstmrMastr,
      }),
    ),
  // 지갑 삭제
  deleteWallet: ({ tbCstmrMastr }: DeleteWalletRequestDTO) =>
    resultify(
      axios.post<DeleteWalletResponseDTO>(`${API_URLS.deleteWallet}`, {
        tbCstmrMastr,
      }),
    ),

  // 지갑 거래내역 목록 조회
  getWalletHistoryList: async ({ paging, search }: WalletHistoryListRequestDTO) => {
    const userRes = getGlobalQueryClient().getQueryData<UserResponse>(
      queries.cstr.cstmr({ cstmrNo: 'detail' }).queryKey,
    );
    const newSearch = {
      ...search,
      walletInsttCd: search?.coinType === TokenItemType.DC1 ? '' : search?.walletInsttCd,
      cstmrNo: userRes?.tbCstmrMastr?.cstmrNo,
    };

    return resultify(
      axios.post<WalletHistoryListResponseDTO>(`${API_URLS.walletReadList}`, {
        paging,
        search: newSearch,
      }),
    );
  },

  // 지갑 상세 조회
  getWalletHistoryDetail: ({ tbAcnutMastr }: WalletHistoryDetailRequestDTO) =>
    resultify(
      axios.post<WalletHistoryDetailResponseDTO>(`${API_URLS.walletRead}`, {
        tbAcnutMastr,
      }),
    ),
} as const;
